IF NOT EXISTS (SELECT * FROM sys.foreign_keys WHERE object_id = OBJECT_ID(N'[dbo].[FK_Company_Client]') AND parent_object_id = OBJECT_ID(N'[dbo].[Company]'))
begin
	ALTER TABLE [dbo].[Company] WITH CHECK ADD CONSTRAINT [FK_Company_Client] FOREIGN KEY([ClientID]) REFERENCES [dbo].[Client] ([ID]);
	ALTER TABLE [dbo].[Company] CHECK CONSTRAINT [FK_Company_Client];
end

IF NOT EXISTS (SELECT * FROM sys.foreign_keys WHERE object_id = OBJECT_ID(N'[dbo].[FK_Company_DatabaseServer]') AND parent_object_id = OBJECT_ID(N'[dbo].[Company]'))
begin
	ALTER TABLE [dbo].[Company]  WITH CHECK ADD  CONSTRAINT [FK_Company_DatabaseServer] FOREIGN KEY([DatabaseServerID]) REFERENCES [dbo].[DatabaseServer] ([ID]);
	ALTER TABLE [dbo].[Company] CHECK CONSTRAINT [FK_Company_DatabaseServer];
end
